// Get email history from Google Sheets
async function getEmailHistory() {
    try {
        const result = await this.helpers.httpRequest({
            method: 'GET',
            url: `https://sheets.googleapis.com/v4/spreadsheets/${cfg.sheets.documentId}/values/${cfg.sheets.emailHistory}`,
            headers: {
                'Authorization': 'Bearer ' + (await this.helpers.getCredentials('googleSheetsOAuth2Api')).access_token
            },
            json: true,
            timeout: 10000
        });

        const history = {};
        if (result.values && result.values.length > 1) {
            const header = result.values[0];
            const emailIndex = header.indexOf('email');
            const lastSentIndex = header.indexOf('lastSent');
            const statusIndex = header.indexOf('status');
            const repliedIndex = header.indexOf('replied');
            const campaignIndex = header.indexOf('campaign');

            if (emailIndex !== -1 && lastSentIndex !== -1) {
                for (let i = 1; i < result.values.length; i++) {
                    const row = result.values[i];
                    if (row[emailIndex] && row[lastSentIndex]) {
                        const email = String(row[emailIndex]).toLowerCase().trim();
                        // Only consider our campaign
                        if (!campaignIndex || row[campaignIndex] === 'SRLINES Pakistan B2B' || !row[campaignIndex]) {
                            const status = statusIndex !== -1 ? row[statusIndex] : '';
                            const replied = repliedIndex !== -1 
                                ? (row[repliedIndex] === 'true' || row[repliedIndex] === 'TRUE' || row[repliedIndex] === '1')
                                : (status === 'replied');

                            history[email] = {
                                lastSent: row[lastSentIndex],
                                status: status,
                                replied: replied,
                                rowIndex: i
                            };
                        }
                    }
                }
            }
        }
        return history;
    } catch (error) {
        console.log('Error reading email history:', error);
        return {};
    }
}

