    // Check cooldown period
    if (emailHistory[email] && emailHistory[email].lastSent) {
        const lastSentTime = new Date(emailHistory[email].lastSent).getTime();
        const daysSinceLastSent = (now - lastSentTime) / (24 * 60 * 60 * 1000);

        if (daysSinceLastSent < cfg.limits.emailCooldownDays) {
